// Client Application Router and Interactivity
import {
  drawLineChart,
  drawBarChart,
  drawDonutChart,
  drawDemographicPyramid,
  formatNumber,
  formatCurrencyIDR,
  renderOverview,
  renderEconomy,
  renderDemographics,
  renderTrade,
  renderProvinces
} from './views.js';

import {
  GDP_TRENDS,
  GDP_BY_SECTOR,
  INFLATION_MONTHLY_2024,
  DEMOGRAPHICS_PYRAMID,
  PROVINCES_DATA
} from './data.js';

let currentSortField = 'population';
let currentSortAsc = false;
let currentSearch = '';
let currentRegion = 'All Regions';

// Setup routing
const routes = {
  '/': { render: renderOverview, title: 'National Overview' },
  '/economy': { render: renderEconomy, title: 'Economic Accounts' },
  '/demographics': { render: renderDemographics, title: 'Demographics & HDI' },
  '/trade': { render: renderTrade, title: 'Trade & Balance of Payments' },
  '/provinces': { render: renderProvinces, title: '38 Regional Provinces' }
};

function navigate() {
  const hash = window.location.hash.slice(1) || '/';
  const cleanHash = hash.startsWith('/') ? hash : '/' + hash;
  const route = routes[cleanHash] || routes['/'];

  // Update page title dynamically
  document.title = `${route.title} — Satu Data Statistik Republik Indonesia`;

  // Update navigation links active state
  document.querySelectorAll('nav.main-nav a').forEach((a) => {
    const target = a.getAttribute('href').replace('#', '');
    if (target === cleanHash) {
      a.classList.add('active');
    } else {
      a.classList.remove('active');
    }
  });

  const root = document.getElementById('app-root');
  if (!root) return;
  root.innerHTML = route.render();
  window.scrollTo(0, 0);

  // Initialize view specific components
  if (cleanHash === '/') {
    initOverviewCharts();
  } else if (cleanHash === '/economy') {
    initEconomyCharts();
  } else if (cleanHash === '/demographics') {
    initDemographicCharts();
  } else if (cleanHash === '/provinces') {
    initProvincesTable();
  }
}

function initOverviewCharts() {
  const gdpCanvas = document.getElementById('canvas-overview-gdp');
  if (gdpCanvas) {
    const labels = GDP_TRENDS.map((g) => g.year.toString());
    const values = GDP_TRENDS.map((g) => g.growth_pct);
    drawLineChart(gdpCanvas, labels, values, {
      lineColor: '#0284c7',
      formatVal: (v) => `${v}%`,
      formatY: (v) => `${v.toFixed(1)}%`
    });
  }

  const sectorCanvas = document.getElementById('canvas-overview-sectors');
  if (sectorCanvas) {
    drawDonutChart(sectorCanvas, GDP_BY_SECTOR);
  }

  const inflCanvas = document.getElementById('canvas-overview-inflation');
  if (inflCanvas) {
    const labels = INFLATION_MONTHLY_2024.map((m) => m.month.split(' ')[0]);
    const values = INFLATION_MONTHLY_2024.map((m) => m.yoy);
    drawLineChart(inflCanvas, labels, values, {
      lineColor: '#e11d48',
      areaColor: 'rgba(225, 29, 72, 0.15)',
      formatVal: (v) => `${v}%`,
      formatY: (v) => `${v.toFixed(1)}%`
    });
  }
}

function initEconomyCharts() {
  const nomCanvas = document.getElementById('canvas-econ-nominal');
  if (nomCanvas) {
    const labels = GDP_TRENDS.map((g) => g.year.toString());
    const values = GDP_TRENDS.map((g) => g.gdp_trillion_idr);
    drawBarChart(nomCanvas, labels, values, {
      barColors: ['#38bdf8', '#0284c7', '#0369a1', '#075985', '#0c4a6e', '#0369a1', '#0284c7'],
      formatVal: (v) => `${v.toFixed(0)} T`,
      formatY: (v) => `${v.toFixed(0)} T`
    });
  }
}

function initDemographicCharts() {
  const pyrCanvas = document.getElementById('canvas-demo-pyramid');
  if (pyrCanvas) {
    drawDemographicPyramid(pyrCanvas, DEMOGRAPHICS_PYRAMID);
  }
}

function initProvincesTable() {
  const tbody = document.getElementById('provinces-tbody');
  const searchInput = document.getElementById('prov-search');
  const regionSelect = document.getElementById('prov-region-filter');
  const resetBtn = document.getElementById('prov-reset-btn');
  const countLabel = document.getElementById('prov-count-label');

  function renderRows() {
    let list = [...PROVINCES_DATA];

    if (currentSearch.trim()) {
      const q = currentSearch.toLowerCase();
      list = list.filter((p) => p.name.toLowerCase().includes(q) || p.capital.toLowerCase().includes(q));
    }

    if (currentRegion !== 'All Regions') {
      list = list.filter((p) => p.region === currentRegion);
    }

    list.sort((a, b) => {
      let valA = a[currentSortField];
      let valB = b[currentSortField];
      if (typeof valA === 'string') {
        return currentSortAsc ? valA.localeCompare(valB) : valB.localeCompare(valA);
      }
      return currentSortAsc ? valA - valB : valB - valA;
    });

    if (countLabel) {
      countLabel.textContent = `Showing ${list.length} of ${PROVINCES_DATA.length} provinces`;
    }

    if (!tbody) return;
    if (list.length === 0) {
      tbody.innerHTML = `<tr><td colspan="8" class="text-center" style="padding:2rem;color:var(--text-muted);">No provinces match the query "${currentSearch}".</td></tr>`;
      return;
    }

    tbody.innerHTML = list.map((p) => `
      <tr>
        <td><strong>${p.name}</strong></td>
        <td><span class="badge-tag neu">${p.region}</span></td>
        <td>${p.capital}</td>
        <td class="text-right"><strong>${formatNumber(p.population)}</strong></td>
        <td class="text-right">${formatCurrencyIDR(p.gdp_per_capita_idr)}</td>
        <td class="text-right"><span class="badge-tag ${p.hdi >= 75 ? 'pos' : p.hdi >= 70 ? 'neu' : 'neg'}">${p.hdi.toFixed(2)}</span></td>
        <td class="text-right">${p.poverty_pct.toFixed(2)}%</td>
        <td class="text-right">${p.unemployment_pct.toFixed(2)}%</td>
      </tr>
    `).join('');
  }

  // Setup table header sort click handlers
  document.querySelectorAll('#provinces-table th[data-sort]').forEach((th) => {
    th.addEventListener('click', () => {
      const field = th.getAttribute('data-sort');
      if (currentSortField === field) {
        currentSortAsc = !currentSortAsc;
      } else {
        currentSortField = field;
        currentSortAsc = field === 'name' || field === 'capital';
      }
      renderRows();
    });
  });

  if (searchInput) {
    searchInput.value = currentSearch;
    searchInput.addEventListener('input', (e) => {
      currentSearch = e.target.value;
      renderRows();
    });
  }

  if (regionSelect) {
    regionSelect.value = currentRegion;
    regionSelect.addEventListener('change', (e) => {
      currentRegion = e.target.value;
      renderRows();
    });
  }

  if (resetBtn) {
    resetBtn.addEventListener('click', () => {
      currentSearch = '';
      currentRegion = 'All Regions';
      currentSortField = 'population';
      currentSortAsc = false;
      if (searchInput) searchInput.value = '';
      if (regionSelect) regionSelect.value = 'All Regions';
      renderRows();
    });
  }

  renderRows();
}

// Global initialization
window.addEventListener('DOMContentLoaded', () => {
  navigate();
  window.addEventListener('hashchange', navigate);
  window.addEventListener('resize', () => {
    // Re-render chart canvases on window resize for crisp responsive redraw
    const hash = window.location.hash.slice(1) || '/';
    const cleanHash = hash.startsWith('/') ? hash : '/' + hash;
    if (cleanHash === '/') initOverviewCharts();
    else if (cleanHash === '/economy') initEconomyCharts();
    else if (cleanHash === '/demographics') initDemographicCharts();
  });
});
```

### app/views.js (23636 bytes)

```js
// View Rendering and Pure Canvas Data Visualizations
import {
  METADATA,
  MACRO_KPI,
  GDP_TRENDS,
  GDP_BY_SECTOR,
  INFLATION_MONTHLY_2024,
  TRADE_DATA,
  DEMOGRAPHICS_PYRAMID,
  PROVINCES_DATA
} from './data.js';

// Formatters
export const formatNumber = (num) => new Intl.NumberFormat('en-US').format(num);
export const formatCurrencyIDR = (num) => `Rp ${formatNumber(num)}`;
export const formatPercent = (num) => `${num.toFixed(2)}%`;

// Pure Canvas Charting Engine (Zero external dependencies)
export function drawLineChart(canvas, labels, values, options = {}) {
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = (options.height || 300) * dpr;
  ctx.scale(dpr, dpr);

  const w = rect.width;
  const h = options.height || 300;
  const padding = { top: 30, right: 30, bottom: 45, left: 60 };
  const chartW = w - padding.left - padding.right;
  const chartH = h - padding.top - padding.bottom;

  ctx.clearRect(0, 0, w, h);

  const minVal = options.min !== undefined ? options.min : Math.min(...values) * 0.95;
  const maxVal = options.max !== undefined ? options.max : Math.max(...values) * 1.05;
  const range = maxVal - minVal || 1;

  // Draw background subtle card canvas glow
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, w, h);

  // Draw grid & Y-axis labels
  ctx.strokeStyle = '#e2e8f0';
  ctx.lineWidth = 1;
  ctx.fillStyle = '#64748b';
  ctx.font = '11px system-ui, sans-serif';
  ctx.textAlign = 'right';

  const gridSteps = 4;
  for (let i = 0; i <= gridSteps; i++) {
    const val = minVal + (range * i) / gridSteps;
    const y = padding.top + chartH - (chartH * i) / gridSteps;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(w - padding.right, y);
    ctx.stroke();
    ctx.fillText(options.formatY ? options.formatY(val) : val.toFixed(1), padding.left - 8, y + 4);
  }

  // Draw line & area fill
  const pts = values.map((v, i) => {
    const x = padding.left + (chartW * i) / (values.length - 1);
    const y = padding.top + chartH - ((v - minVal) / range) * chartH;
    return { x, y, v, label: labels[i] };
  });

  // Area gradient
  const grad = ctx.createLinearGradient(0, padding.top, 0, padding.top + chartH);
  grad.addColorStop(0, options.areaColor || 'rgba(2, 132, 199, 0.25)');
  grad.addColorStop(1, 'rgba(2, 132, 199, 0.0)');
  ctx.beginPath();
  ctx.moveTo(pts[0].x, padding.top + chartH);
  pts.forEach((p) => ctx.lineTo(p.x, p.y));
  ctx.lineTo(pts[pts.length - 1].x, padding.top + chartH);
  ctx.closePath();
  ctx.fillStyle = grad;
  ctx.fill();

  // Line
  ctx.beginPath();
  pts.forEach((p, i) => {
    if (i === 0) ctx.moveTo(p.x, p.y);
    else ctx.lineTo(p.x, p.y);
  });
  ctx.strokeStyle = options.lineColor || '#0284c7';
  ctx.lineWidth = 3;
  ctx.stroke();

  // Points & X labels
  ctx.textAlign = 'center';
  pts.forEach((p) => {
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(p.x, p.y, 4.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = options.lineColor || '#0284c7';
    ctx.lineWidth = 2.5;
    ctx.stroke();

    // Value on top
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 11px system-ui, sans-serif';
    ctx.fillText(options.formatVal ? options.formatVal(p.v) : p.v, p.x, p.y - 9);

    // Label below
    ctx.fillStyle = '#64748b';
    ctx.font = '11px system-ui, sans-serif';
    ctx.fillText(p.label, p.x, h - padding.bottom + 18);
  });
}

export function drawBarChart(canvas, labels, values, options = {}) {
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = (options.height || 300) * dpr;
  ctx.scale(dpr, dpr);

  const w = rect.width;
  const h = options.height || 300;
  const padding = { top: 25, right: 25, bottom: 45, left: options.leftPad || 65 };
  const chartW = w - padding.left - padding.right;
  const chartH = h - padding.top - padding.bottom;

  ctx.clearRect(0, 0, w, h);

  const maxVal = Math.max(...values, 0) * 1.15 || 10;
  const minVal = Math.min(...values, 0);

  // Y-axis grid
  ctx.strokeStyle = '#f1f5f9';
  ctx.fillStyle = '#64748b';
  ctx.font = '11px system-ui, sans-serif';
  ctx.textAlign = 'right';

  const steps = 4;
  for (let i = 0; i <= steps; i++) {
    const val = (maxVal * i) / steps;
    const y = padding.top + chartH - (chartH * i) / steps;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(w - padding.right, y);
    ctx.stroke();
    ctx.fillText(options.formatY ? options.formatY(val) : val.toFixed(1), padding.left - 8, y + 4);
  }

  const barCount = values.length;
  const totalBarSpace = chartW / barCount;
  const barWidth = Math.min(totalBarSpace * 0.65, 45);

  labels.forEach((lbl, i) => {
    const v = values[i];
    const barH = (v / maxVal) * chartH;
    const x = padding.left + i * totalBarSpace + (totalBarSpace - barWidth) / 2;
    const y = padding.top + chartH - barH;

    ctx.fillStyle = options.barColors ? options.barColors[i % options.barColors.length] : '#0284c7';
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(x, y, barWidth, barH, [4, 4, 0, 0]) : ctx.rect(x, y, barWidth, barH);
    ctx.fill();

    // Value label
    ctx.fillStyle = '#1e293b';
    ctx.font = 'bold 10px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(options.formatVal ? options.formatVal(v) : v, x + barWidth / 2, y - 6);

    // X label
    ctx.fillStyle = '#64748b';
    ctx.font = '10px system-ui, sans-serif';
    ctx.fillText(lbl, x + barWidth / 2, h - padding.bottom + 18);
  });
}

export function drawDonutChart(canvas, items) {
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = 280 * dpr;
  ctx.scale(dpr, dpr);

  const w = rect.width;
  const h = 280;
  ctx.clearRect(0, 0, w, h);

  const cx = w * 0.35;
  const cy = h * 0.5;
  const r = Math.min(cx, cy) - 25;
  const innerR = r * 0.6;

  let startAngle = -Math.PI / 2;
  const total = items.reduce((acc, it) => acc + it.share_pct, 0);

  items.forEach((it) => {
    const sliceAngle = (it.share_pct / total) * Math.PI * 2;
    ctx.beginPath();
    ctx.arc(cx, cy, r, startAngle, startAngle + sliceAngle);
    ctx.arc(cx, cy, innerR, startAngle + sliceAngle, startAngle, true);
    ctx.closePath();
    ctx.fillStyle = it.color || '#3b82f6';
    ctx.fill();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.stroke();
    startAngle += sliceAngle;
  });

  // Center text
  ctx.fillStyle = '#0f172a';
  ctx.font = 'bold 15px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('GDP Sector', cx, cy - 3);
  ctx.fillStyle = '#64748b';
  ctx.font = '11px system-ui, sans-serif';
  ctx.fillText('Distribution', cx, cy + 14);

  // Legend on right
  const legendX = cx + r + 30;
  let legendY = 35;
  ctx.textAlign = 'left';
  items.slice(0, 7).forEach((it) => {
    ctx.fillStyle = it.color;
    ctx.fillRect(legendX, legendY - 9, 10, 10);
    ctx.fillStyle = '#1e293b';
    ctx.font = '11px system-ui, sans-serif';
    ctx.fillText(`${it.share_pct}% ${it.sector.split('(')[0].trim()}`, legendX + 16, legendY);
    legendY += 28;
  });
}

export function drawDemographicPyramid(canvas, pyramidData) {
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = 360 * dpr;
  ctx.scale(dpr, dpr);

  const w = rect.width;
  const h = 360;
  const pad = { top: 30, right: 30, bottom: 30, left: 30 };
  const chartW = w - pad.left - pad.right;
  const chartH = h - pad.top - pad.bottom;
  const cx = pad.left + chartW / 2;

  ctx.clearRect(0, 0, w, h);

  const maxPop = 14; // in millions
  const rowCount = pyramidData.length;
  const rowH = chartH / rowCount;
  const halfW = (chartW - 70) / 2;

  // Header Legend
  ctx.font = 'bold 11px system-ui, sans-serif';
  ctx.textAlign = 'right';
  ctx.fillStyle = '#0284c7';
  ctx.fillText('◄ Male Population (M)', cx - 40, pad.top - 12);
  ctx.textAlign = 'left';
  ctx.fillStyle = '#ec4899';
  ctx.fillText('Female Population (M) ►', cx + 40, pad.top - 12);

  pyramidData.forEach((d, i) => {
    const y = pad.top + i * rowH;
    const bH = rowH * 0.72;

    // Male bar (left)
    const mW = (d.male_m / maxPop) * halfW;
    ctx.fillStyle = '#38bdf8';
    ctx.fillRect(cx - 30 - mW, y, mW, bH);

    // Female bar (right)
    const fW = (d.female_m / maxPop) * halfW;
    ctx.fillStyle = '#f472b6';
    ctx.fillRect(cx + 30, y, fW, bH);

    // Age text in center
    ctx.fillStyle = '#475569';
    ctx.font = '10px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(d.age, cx, y + bH * 0.75);
  });
}

// VIEW 1: Overview
export function renderOverview() {
  const kpisHtml = MACRO_KPI.map((kpi) => `
    <div class="kpi-card">
      <div class="kpi-card-header">
        <span class="kpi-title">${kpi.label}</span>
        <span class="badge-tag ${kpi.changeType === 'positive' ? 'pos' : kpi.changeType === 'negative' ? 'neg' : 'neu'}">${kpi.change}</span>
      </div>
      <div class="kpi-value">${kpi.value}</div>
      <div class="kpi-sub">${kpi.baseline || kpi.usd || ''} • ${kpi.period}</div>
      <div class="kpi-source">${kpi.source}</div>
    </div>
  `).join('');

  return `
    <div class="page-banner">
      <div class="banner-content">
        <h2>Satu Data Statistik Republik Indonesia</h2>
        <p>Official national statistical portal presenting certified, evidence-based economic, demographic, and regional indicators published by Badan Pusat Statistik (BPS) and Bank Indonesia.</p>
      </div>
      <div class="banner-badge">
        <strong>Official Data Release:</strong> ${METADATA.last_updated}<br>
        <strong>Sovereign State:</strong> ${METADATA.country} (${METADATA.country_id})
      </div>
    </div>

    <div class="kpi-grid">
      ${kpisHtml}
    </div>

    <div class="grid-2">
      <div class="section-card">
        <div class="section-header">
          <div>
            <h3>GDP Economic Growth Trajectory (2018–2024)</h3>
            <p>Annual real GDP growth rate (y-on-y % change) • Source: BPS BRS</p>
          </div>
        </div>
        <div class="chart-container">
          <canvas id="canvas-overview-gdp" class="stat-canvas"></canvas>
        </div>
      </div>

      <div class="section-card">
        <div class="section-header">
          <div>
            <h3>Gross Domestic Product by Industrial Origin</h3>
            <p>Percentage contribution to total GDP (Q3 2024) • Source: BPS</p>
          </div>
        </div>
        <div class="chart-container">
          <canvas id="canvas-overview-sectors" class="stat-canvas"></canvas>
        </div>
      </div>
    </div>

    <div class="section-card">
      <div class="section-header">
        <div>
          <h3>Monthly Headline Inflation Trend (Jan–Oct 2024)</h3>
          <p>Year-on-year consumer price index inflation rate (%) within Bank Indonesia target 2.5 ± 1%</p>
        </div>
      </div>
