/* Satu Data Indonesia - Modern National Statistics Design System */
:root {
  --primary: #0284c7;
  --primary-dark: #0369a1;
  --primary-light: #e0f2fe;
  --secondary: #0f172a;
  --accent: #f59e0b;
  --accent-red: #ef4444;
  --accent-green: #10b981;
  --bg-main: #f8fafc;
  --bg-card: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border: #e2e8f0;
  --border-focus: #38bdf8;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-md: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 14px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg-main);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* Header & Navigation */
header.site-header {
  background-color: #ffffff;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.header-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0.85rem 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
  color: inherit;
}

.brand-flag {
  width: 32px;
  height: 22px;
  border-radius: 3px;
  box-shadow: 0 0 0 1px rgba(0,0,0,0.1);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.brand-flag .red { background-color: #e11d48; flex: 1; }
.brand-flag .white { background-color: #ffffff; flex: 1; }

.brand-text h1 {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--secondary);
  line-height: 1.2;
}

.brand-text span {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
}

nav.main-nav {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

nav.main-nav a {
  text-decoration: none;
  color: var(--text-muted);
  padding: 0.45rem 0.85rem;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 600;
  transition: all 0.15s ease-in-out;
}

nav.main-nav a:hover {
  background-color: var(--primary-light);
  color: var(--primary-dark);
}

nav.main-nav a.active {
  background-color: var(--primary);
  color: #ffffff;
}

/* Main Container */
main#app-root {
  max-width: 1280px;
  margin: 1.5rem auto 3rem;
  padding: 0 1.25rem;
}

/* Page Intro Banner */
.page-banner {
  background: linear-gradient(135deg, #0369a1 0%, #0f172a 100%);
  color: #ffffff;
  padding: 2rem 2.25rem;
  border-radius: var(--radius-lg);
  margin-bottom: 2rem;
  box-shadow: var(--shadow);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1.5rem;
}

.banner-content h2 {
  font-size: 1.75rem;
  font-weight: 800;
  margin-bottom: 0.4rem;
  letter-spacing: -0.02em;
}

.banner-content p {
  color: #bae6fd;
  font-size: 0.95rem;
  max-width: 650px;
}

.banner-badge {
  background: rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(8px);
  padding: 0.65rem 1.15rem;
  border-radius: var(--radius);
  font-size: 0.825rem;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

/* KPI Cards Grid */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 1.25rem;
  margin-bottom: 2.5rem;
}

.kpi-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  box-shadow: var(--shadow-sm);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  position: relative;
  overflow: hidden;
}

.kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.kpi-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 0.65rem;
}

.kpi-title {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
}

.kpi-value {
  font-size: 1.85rem;
  font-weight: 800;
  color: var(--secondary);
  line-height: 1.15;
  margin-bottom: 0.35rem;
}

.kpi-sub {
  font-size: 0.8rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.badge-tag {
  display: inline-block;
  padding: 0.15rem 0.45rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
}
.badge-tag.pos { background: #dcfce7; color: #15803d; }
.badge-tag.neu { background: #f1f5f9; color: #475569; }
.badge-tag.neg { background: #fee2e2; color: #b91c1c; }

.kpi-source {
  margin-top: 0.65rem;
  font-size: 0.7rem;
  color: #94a3b8;
  border-top: 1px dashed var(--border);
  padding-top: 0.45rem;
}

/* Section Containers */
.section-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  margin-bottom: 2rem;
  box-shadow: var(--shadow-sm);
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.section-header h3 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--secondary);
}

.section-header p {
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* Charts & Canvases */
.chart-container {
  width: 100%;
  position: relative;
  margin: 1rem 0;
  background: #ffffff;
  border-radius: var(--radius);
}

canvas.stat-canvas {
  width: 100%;
  height: 320px;
  display: block;
}

/* Interactive Controls & Filters */
.controls-bar {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 1.25rem;
  background: #f1f5f9;
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
}

.filter-input {
  padding: 0.5rem 0.85rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  background: #ffffff;
  outline: none;
  min-width: 220px;
}

.filter-input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary-light);
}

.filter-select {
  padding: 0.5rem 0.85rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  background: #ffffff;
  outline: none;
  cursor: pointer;
}

.btn {
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 600;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.15s ease;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.btn-primary {
  background: var(--primary);
  color: #ffffff;
}
.btn-primary:hover {
  background: var(--primary-dark);
}

.btn-outline {
  background: #ffffff;
  border-color: var(--border);
  color: var(--text-main);
}
.btn-outline:hover {
  background: #f8fafc;
  border-color: #cbd5e1;
}

/* Data Tables */
.table-responsive {
  width: 100%;
  overflow-x: auto;
  border-radius: var(--radius);
  border: 1px solid var(--border);
}

table.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

table.data-table th {
  background-color: #f8fafc;
  color: #475569;
  font-weight: 700;
  padding: 0.85rem 1rem;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
  user-select: none;
  cursor: pointer;
}

table.data-table th:hover {
  background-color: #f1f5f9;
  color: var(--primary);
}

table.data-table td {
  padding: 0.85rem 1rem;
  border-bottom: 1px solid #f1f5f9;
  color: var(--text-main);
}

table.data-table tr:last-child td {
  border-bottom: none;
}

table.data-table tr:hover {
  background-color: #f8fafc;
}

.text-right { text-align: right; }
.text-center { text-align: center; }

/* Grid 2 Columns */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(450px, 1fr));
  gap: 1.5rem;
}

/* Footer */
footer.site-footer {
  background: #ffffff;
  border-top: 1px solid var(--border);
  padding: 2.5rem 1.25rem;
  color: var(--text-muted);
  font-size: 0.85rem;
}

.footer-container {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 2rem;
}

.footer-col h4 {
  color: var(--secondary);
  font-size: 0.95rem;
  font-weight: 700;
  margin-bottom: 0.65rem;
}

.footer-col p {
  max-width: 380px;
  line-height: 1.6;
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: 0.4rem;
}

.footer-links a {
  color: var(--primary);
  text-decoration: none;
}

.footer-bottom {
  max-width: 1280px;
  margin: 2rem auto 0;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
  text-align: center;
  font-size: 0.8rem;
  color: #94a3b8;
}

/* Mobile & Responsive Adjustments */
@media (max-width: 768px) {
  .header-container {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.75rem;
  }
  nav.main-nav {
    width: 100%;
    overflow-x: auto;
    padding-bottom: 0.25rem;
  }
  .page-banner {
    padding: 1.5rem;
  }
  .banner-content h2 {
    font-size: 1.4rem;
  }
  .grid-2 {
    grid-template-columns: 1fr;
  }
  .controls-bar {
    flex-direction: column;
    align-items: stretch;
  }
  .filter-input {
    min-width: 100%;
  }
  canvas.stat-canvas {
    height: 240px;
  }
}
